function validate([root, p]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root.';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Node values are integers between -10^5 and 10^5.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  if (!values.includes(p)) return 'p must be a value in the tree.';
  // Link the level-order array into child indexes, then walk it in order: a BST gives rising values.
  const left = [], right = [], queue = [0];
  let next = 1;
  for (let k = 0; k < queue.length && next < root.length; k++) {
    const at = queue[k];
    if (next < root.length && root[next] !== null) { left[at] = next; queue.push(next); }
    next++;
    if (next < root.length && root[next] !== null) { right[at] = next; queue.push(next); }
    next++;
  }
  const stack = [];
  let at = 0, previous = -Infinity;
  while (at !== undefined || stack.length) {
    while (at !== undefined) { stack.push(at); at = left[at]; }
    at = stack.pop();
    if (root[at] <= previous) return 'The tree must be a binary search tree.';
    previous = root[at];
    at = right[at];
  }
  return null;
}

