  // List every node in order with an explicit stack, then take the one after p.
  const order = [];
  const stack = [];
  let node = root;
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop();
    order.push(node);
    node = node.right;
  }
  const index = order.indexOf(p);
  return index + 1 < order.length ? order[index + 1] : null;
